<script setup lang="ts">
import { reactive, watch } from 'vue'
import type { AgentConfig } from '@/types/domain'
const props = defineProps<{ config: AgentConfig; saving: boolean }>(); const emit = defineEmits<{ save: [config: AgentConfig] }>(); const draft = reactive<AgentConfig>({ ...props.config })
watch(() => props.config, (value) => Object.assign(draft, value), { deep: true })
function submit() { emit('save', { ...draft }) }
</script>
<template><el-form class="config-form" label-position="top"><div class="form-section"><div class="form-section-title"><span>模型链路</span><small>主生成模型和 API Key 由上方“行政助手”卡片控制</small></div><div class="form-grid"><el-form-item label="回退生成模型"><el-input v-model="draft.generation_model" /></el-form-item><el-form-item label="上下文理解模型"><el-input v-model="draft.context_model" placeholder="qwen-flash" /></el-form-item><el-form-item label="Embedding 模型"><el-input v-model="draft.embedding_model" /></el-form-item><el-form-item label="Rerank 模型"><el-input v-model="draft.rerank_model" /></el-form-item><el-form-item label="温度"><el-input-number v-model="draft.temperature" :min="0" :max="1" :step="0.05" /></el-form-item></div></div><div class="form-section"><div class="form-section-title"><span>检索与生成</span><small>修改后先保存草稿，再运行评测并发布</small></div><div class="form-grid"><el-form-item label="初始召回数量"><el-input-number v-model="draft.retrieval_top_k" :min="5" :max="100" /></el-form-item><el-form-item label="送入模型的引用数"><el-input-number v-model="draft.rerank_top_n" :min="1" :max="10" /></el-form-item><el-form-item label="最低相关度"><el-slider v-model="draft.score_threshold" :min="0" :max="1" :step="0.05" show-input /></el-form-item><el-form-item label="最大输出 Token"><el-input-number v-model="draft.max_output_tokens" :min="256" :max="8000" :step="128" /></el-form-item><el-form-item label="上下文预算"><el-input-number v-model="draft.context_budget" :min="2000" :max="50000" :step="1000" /></el-form-item><el-form-item label="超时时间（秒）"><el-input-number v-model="draft.timeout_seconds" :min="10" :max="180" /></el-form-item></div></div><div class="form-section"><div class="form-section-title"><span>系统提示词</span><small>制度内容被视为不可信数据，服务端会附加防提示注入约束</small></div><el-input v-model="draft.system_prompt" type="textarea" :rows="7" maxlength="4000" show-word-limit /></div><div class="config-actions"><el-button type="primary" :loading="saving" @click="submit">保存为新草稿</el-button></div></el-form></template>
